import {
    Table,
    BooleanColumn,
    DomainIdColumn,
    DomainPathColumn,
    GenericColumn,
    GuidColumn,
    IntegerColumn,
    JsonColumn,
    ReferenceColumn,
    StringColumn,
    TranslatedFieldColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_ux_screen = Table({
    actions: {
        read: true,
        update: true,
        delete: true,
        create: true,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_text_index: true,
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'UX Screen',
    name: 'sys_ux_screen',
    schema: {
        required_translations: GenericColumn({
            columnType: 'json_translations',
            label: [
                {
                    hint: 'JSON Array, holding the translations required by this screen',
                    label: 'Required translations',
                    plural: 'Required translations',
                },
            ],
            maxLength: 8000,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
            maxLength: 255,
        }),
        screen_condition: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'Screen Condition',
            maxLength: 512,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
            maxLength: 40,
        }),
        description: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Description',
            maxLength: 4000,
        }),
        disable_interoperable: BooleanColumn({
            label: [
                {
                    hint: 'Disable usage of this screen in other experiences.',
                    label: 'Restrict use across experiences',
                    plural: 'Restrict use across experiences',
                },
            ],
            maxLength: 40,
        }),
        sys_overrides: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Override',
            maxLength: 32,
            referenceTable: 'sys_ux_screen',
        }),
        event_mappings: JsonColumn({
            label: 'Event Mappings',
            maxLength: 8000,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            maxLength: 32,
            primary: true,
        }),
        screen_type: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: 'Screen Collection',
            maxLength: 32,
            referenceTable: 'sys_ux_screen_type',
        }),
        parent_macroponent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            cascadeRule: 'delete',
            label: [
                {
                    hint: 'Macroponent that contains this screen',
                    label: 'Parent Macroponent',
                    plural: 'Parent Macroponents',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_macroponent',
        }),
        disable_auto_reflow: BooleanColumn({
            default: false,
            label: 'Disable Auto Reflow',
            maxLength: 40,
        }),
        name: TranslatedFieldColumn({
            label: [
                {
                    hint: 'Name of the screen',
                    label: 'Screen Name',
                    plural: 'Screen Names',
                },
            ],
            mandatory: true,
            maxLength: 255,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: 'Domain',
            maxLength: 32,
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        macroponent_config: JsonColumn({
            label: 'Macroponent Configuration',
            maxLength: 8000,
        }),
        macroponent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Page Definition',
            mandatory: true,
            maxLength: 32,
            referenceTable: 'sys_ux_macroponent',
            referenceQual: 'category=page^EQ',
            useReferenceQualifier: 'simple',
        }),
        app_config: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'App to use this router configuration',
                    label: 'App Configuration',
                    plural: 'App Configurations',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_app_config',
        }),
        rollback_screen: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Screen for rollback',
                    label: 'Rollback screen',
                    plural: 'Rollback screens',
                },
            ],
            maxLength: 32,
            referenceTable: 'sys_ux_screen',
        }),
        order: IntegerColumn({
            default: '0',
            label: 'Order',
            maxLength: 40,
        }),
    },
    textIndex: true,
})
